import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';

export interface Question {
  id: string;
  text: string;
  options?: string[];
  correctAnswer?: number;
  mu: number;
  sigma: number;
  tags: string[];
  questionType: 'multiple-choice' | 'student-produced';
}

interface QuestionTimeTracking {
  questionId: string;
  timeSpent: number;
  startTime: number | null;
  endTime: number | null;
  visits: number;
}

interface Answer {
  questionId: string;
  selectedOption?: number;
  textAnswer?: string;
  isMarkedForReview: boolean;
  isCorrect?: boolean;
}

interface TestContextValue {
  testId: string | null;
  testType: 'quiz' | 'custom' | 'exam' | null;
  questions: Question[];
  currentQuestionIndex: number;
  answers: Answer[];
  timeTracking: QuestionTimeTracking[];
  testStartTime: number | null;
  testEndTime: number | null;
  testDuration: number; // in seconds
  remainingTime: number;
  isTestComplete: boolean;
  loading: boolean;
  error: string | null;
  
  // Navigation functions
  goToNextQuestion: () => void;
  goToPreviousQuestion: () => void;
  goToQuestion: (index: number) => void;
  
  // Answer management
  setAnswer: (answer: { selectedOption?: number; textAnswer?: string }) => void;
  toggleMarkForReview: () => void;
  
  // Test control functions
  startTest: (testType: 'quiz' | 'custom' | 'exam', topics: string[], questionCount: number) => Promise<void>;
  submitTest: () => Promise<void>;
  exitTest: () => void;
}

const TestContext = createContext<TestContextValue | undefined>(undefined);

interface TestProviderProps {
  children: ReactNode;
}

const MINUTE_IN_SECONDS = 60;
const DEFAULT_TEST_DURATION = 70 * MINUTE_IN_SECONDS; // 70 minutes in seconds

export const TestProvider: React.FC<TestProviderProps> = ({ children }) => {
  // Test state
  const [testId, setTestId] = useState<string | null>(null);
  const [testType, setTestType] = useState<'quiz' | 'custom' | 'exam' | null>(null);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [answers, setAnswers] = useState<Answer[]>([]);
  const [timeTracking, setTimeTracking] = useState<QuestionTimeTracking[]>([]);
  const [testStartTime, setTestStartTime] = useState<number | null>(null);
  const [testEndTime, setTestEndTime] = useState<number | null>(null);
  const [testDuration, setTestDuration] = useState<number>(DEFAULT_TEST_DURATION);
  const [remainingTime, setRemainingTime] = useState<number>(DEFAULT_TEST_DURATION);
  const [isTestComplete, setIsTestComplete] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [timerInterval, setTimerInterval] = useState<NodeJS.Timeout | null>(null);

  // Initialize time tracking for a question
  const initializeTimeTrackingForQuestion = (questionId: string) => {
    return {
      questionId,
      timeSpent: 0,
      startTime: null,
      endTime: null,
      visits: 0,
    };
  };

  // Start tracking time for the current question
  useEffect(() => {
    if (!testStartTime || isTestComplete) return;

    // End tracking for previous question if any
    setTimeTracking(prev => prev.map(track => {
      if (track.startTime && !track.endTime) {
        return {
          ...track,
          endTime: Date.now(),
          timeSpent: track.timeSpent + (Date.now() - (track.startTime || 0)) / 1000,
        };
      }
      return track;
    }));

    if (questions.length > 0) {
      const currentQuestionId = questions[currentQuestionIndex]?.id;
      if (!currentQuestionId) return;

      setTimeTracking(prev => {
        const questionTrackIndex = prev.findIndex(t => t.questionId === currentQuestionId);

        if (questionTrackIndex >= 0) {
          // Update existing tracking
          const updatedTracks = [...prev];
          updatedTracks[questionTrackIndex] = {
            ...updatedTracks[questionTrackIndex],
            startTime: Date.now(),
            endTime: null,
            visits: updatedTracks[questionTrackIndex].visits + 1,
          };
          return updatedTracks;
        } else {
          // Create new tracking
          return [
            ...prev,
            {
              ...initializeTimeTrackingForQuestion(currentQuestionId),
              startTime: Date.now(),
              visits: 1,
            },
          ];
        }
      });
    }

    // Clean up timer on component unmount
    return () => {
      setTimeTracking(prev => prev.map(track => {
        if (track.startTime && !track.endTime) {
          return {
            ...track,
            endTime: Date.now(),
            timeSpent: track.timeSpent + (Date.now() - (track.startTime || 0)) / 1000,
          };
        }
        return track;
      }));
    };
  }, [currentQuestionIndex, testStartTime, questions, isTestComplete]);

  // Main test timer
  useEffect(() => {
    if (!testStartTime || isTestComplete) {
      if (timerInterval) {
        clearInterval(timerInterval);
        setTimerInterval(null);
      }
      return;
    }

    // Set up timer
    const interval = setInterval(() => {
      const elapsedSeconds = Math.floor((Date.now() - testStartTime) / 1000);
      const remaining = Math.max(0, testDuration - elapsedSeconds);
      
      setRemainingTime(remaining);

      if (remaining <= 0) {
        // Time's up, auto-submit
        clearInterval(interval);
        submitTest();
      }
    }, 1000);

    setTimerInterval(interval);

    return () => {
      clearInterval(interval);
    };
  }, [testStartTime, testDuration, isTestComplete]);

  // Navigation functions
  const goToNextQuestion = () => {
    if (currentQuestionIndex < questions.length - 1) {
      setCurrentQuestionIndex(currentQuestionIndex + 1);
    }
  };

  const goToPreviousQuestion = () => {
    if (currentQuestionIndex > 0) {
      setCurrentQuestionIndex(currentQuestionIndex - 1);
    }
  };

  const goToQuestion = (index: number) => {
    if (index >= 0 && index < questions.length) {
      setCurrentQuestionIndex(index);
    }
  };

  // Answer management
  const setAnswer = ({ selectedOption, textAnswer }: { selectedOption?: number; textAnswer?: string }) => {
    if (questions.length === 0 || isTestComplete) return;

    const currentQuestion = questions[currentQuestionIndex];
    const existingAnswerIndex = answers.findIndex(a => a.questionId === currentQuestion.id);

    if (existingAnswerIndex >= 0) {
      const updatedAnswers = [...answers];
      updatedAnswers[existingAnswerIndex] = {
        ...updatedAnswers[existingAnswerIndex],
        selectedOption,
        textAnswer,
      };
      setAnswers(updatedAnswers);
    } else {
      setAnswers([
        ...answers,
        {
          questionId: currentQuestion.id,
          selectedOption,
          textAnswer,
          isMarkedForReview: false,
        },
      ]);
    }
  };

  const toggleMarkForReview = () => {
    if (questions.length === 0 || isTestComplete) return;

    const currentQuestion = questions[currentQuestionIndex];
    const existingAnswerIndex = answers.findIndex(a => a.questionId === currentQuestion.id);

    if (existingAnswerIndex >= 0) {
      const updatedAnswers = [...answers];
      updatedAnswers[existingAnswerIndex] = {
        ...updatedAnswers[existingAnswerIndex],
        isMarkedForReview: !updatedAnswers[existingAnswerIndex].isMarkedForReview,
      };
      setAnswers(updatedAnswers);
    } else {
      setAnswers([
        ...answers,
        {
          questionId: currentQuestion.id,
          isMarkedForReview: true,
        },
      ]);
    }
  };

  // Fetch questions from the server based on test configuration
  const fetchQuestions = async (testType: 'quiz' | 'custom' | 'exam', topics: string[], count: number): Promise<Question[]> => {
    try {
      const response = await fetch('/api/questions/fetch', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`,
        },
        body: JSON.stringify({ testType, topics, count }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to fetch questions');
      }

      const data = await response.json();
      return data.questions;
    } catch (error) {
      console.error('Error fetching questions:', error);
      throw error;
    }
  };

  // Test control functions
  const startTest = async (testType: 'quiz' | 'custom' | 'exam', topics: string[], questionCount: number) => {
    try {
      setLoading(true);
      setError(null);

      // Fetch questions
      const fetchedQuestions = await fetchQuestions(testType, topics, questionCount);

      // Calculate test duration based on number of questions
      const calculatedDuration = Math.ceil((70 / 44) * questionCount * MINUTE_IN_SECONDS);
      
      // Initialize test state
      const startTime = Date.now();
      
      setTestId(`test-${startTime}`);
      setTestType(testType);
      setQuestions(fetchedQuestions);
      setCurrentQuestionIndex(0);
      setAnswers([]);
      setTimeTracking([]);
      setTestStartTime(startTime);
      setTestEndTime(null);
      setTestDuration(calculatedDuration);
      setRemainingTime(calculatedDuration);
      setIsTestComplete(false);
      
      // Initialize time tracking for first question
      if (fetchedQuestions.length > 0) {
        setTimeTracking([
          {
            questionId: fetchedQuestions[0].id,
            timeSpent: 0,
            startTime: startTime,
            endTime: null,
            visits: 1,
          }
        ]);
      }
    } catch (error: any) {
      setError(error.message || 'Failed to start test');
    } finally {
      setLoading(false);
    }
  };

  const submitTest = async () => {
    if (!testId || questions.length === 0) return;

    try {
      setLoading(true);
      
      // Calculate final time spent on each question
      const finalTimeTracking = timeTracking.map(track => {
        if (track.startTime && !track.endTime) {
          return {
            ...track,
            endTime: Date.now(),
            timeSpent: track.timeSpent + (Date.now() - (track.startTime || 0)) / 1000,
          };
        }
        return track;
      });

      const endTime = Date.now();

      // Process and submit answers
      // Here you would grade answers if needed and prepare for submission
      // For this implementation, we'll just simulate the submission

      // Update test state
      setTimeTracking(finalTimeTracking);
      setTestEndTime(endTime);
      setIsTestComplete(true);

      // Clear timer
      if (timerInterval) {
        clearInterval(timerInterval);
        setTimerInterval(null);
      }

      // Here you would submit the test results to your backend
      // await submitTestResults(...)
      
      // For now we'll just simulate it
      console.log('Test submitted', {
        testId,
        testType,
        startTime: testStartTime,
        endTime,
        duration: (endTime - (testStartTime || 0)) / 1000,
        answers,
        timeTracking: finalTimeTracking,
      });

      // Navigate to results page would be handled by the component

    } catch (error: any) {
      setError(error.message || 'Failed to submit test');
    } finally {
      setLoading(false);
    }
  };

  const exitTest = () => {
    // Clean up test state
    if (timerInterval) {
      clearInterval(timerInterval);
      setTimerInterval(null);
    }

    // Reset all state
    setTestId(null);
    setTestType(null);
    setQuestions([]);
    setCurrentQuestionIndex(0);
    setAnswers([]);
    setTimeTracking([]);
    setTestStartTime(null);
    setTestEndTime(null);
    setTestDuration(DEFAULT_TEST_DURATION);
    setRemainingTime(DEFAULT_TEST_DURATION);
    setIsTestComplete(false);
    setError(null);
  };

  // Create context value
  const contextValue: TestContextValue = {
    testId,
    testType,
    questions,
    currentQuestionIndex,
    answers,
    timeTracking,
    testStartTime,
    testEndTime,
    testDuration,
    remainingTime,
    isTestComplete,
    loading,
    error,
    
    goToNextQuestion,
    goToPreviousQuestion,
    goToQuestion,
    
    setAnswer,
    toggleMarkForReview,
    
    startTest,
    submitTest,
    exitTest,
  };

  return (
    <TestContext.Provider value={contextValue}>
      {children}
    </TestContext.Provider>
  );
};

export const useTest = (): TestContextValue => {
  const context = useContext(TestContext);
  if (context === undefined) {
    throw new Error('useTest must be used within a TestProvider');
  }
  return context;
};
